package com.example.commerce.review; import javax.validation.Valid; import javax.validation.constraints.*; import com.example.commerce.common.CommerceException; import com.example.commerce.config.SecurityConfig; import com.example.commerce.order.*; import com.example.commerce.product.*; import com.example.commerce.user.User; import lombok.*; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
@RestController @Transactional public class ReviewController{private final ReviewRepository reviews;private final ProductRepository products;private final OrderRepository orders;public ReviewController(ReviewRepository r,ProductRepository p,OrderRepository o){reviews=r;products=p;orders=o;}@Getter @Setter public static class Request{@Min(1)@Max(5)int rating;@NotBlank @Size(max=2000)String comment;}@Getter @AllArgsConstructor public static class Response{long id;int rating;String comment;String customer;boolean verifiedPurchase;}@PostMapping("/api/products/{id}/reviews")@PreAuthorize("hasRole('CUSTOMER')")ResponseEntity<Response> create(@PathVariable Long id,@Valid @RequestBody Request r){User u=SecurityConfig.currentUser();if(reviews.findByUserIdAndProductId(u.getId(),id).isPresent())throw new CommerceException(HttpStatus.CONFLICT,"Only one review per product is allowed");Product p=products.findById(id).orElseThrow(()->new CommerceException(HttpStatus.NOT_FOUND,"Product not found"));boolean verified=orders.findByUserId(u.getId(),Pageable.unpaged()).stream().filter(o->o.getStatus()==OrderStatus.DELIVERED).flatMap(o->o.getItems().stream()).anyMatch(i->i.getProductId().equals(id));Review v=new Review();v.setUser(u);v.setProduct(p);v.setRating(r.getRating());v.setComment(r.getComment().trim());v.setVerifiedPurchase(verified);v=reviews.save(v);return ResponseEntity.status(201).body(map(v));}@GetMapping("/api/products/{id}/reviews")@Transactional(readOnly=true)Page<Response> list(@PathVariable Long id,Pageable p){return reviews.findByProductId(id,p).map(this::map);}private Response map(Review r){return new Response(r.getId(),r.getRating(),r.getComment(),r.getUser().getName(),r.isVerifiedPurchase());}}
